73	/**
74	 * 仮想物体の描画結果 (リニア、アルファ乗算済み) を、カメラの映像の上に重ねて sRGB で出力する。
75	 * カメラの映像は、枠の中の各画素が向いている方向を、カメラから見た方向に直して引く。
76	 * 景色は十分遠くにあるものとして、頭とカメラの位置の差は無視している。
77	 */
78	const COMPOSITE_FRAGMENT = /* glsl */ `
79	uniform sampler2D virtualMap;
80	uniform sampler2D videoMap;
81	uniform bool hasVideo;
82	uniform mat3 toVideo;
83	uniform vec2 captureTan;
84	uniform vec2 videoTan;
85	uniform vec3 backdrop;
86	varying vec2 vNdc;
87	
88	vec3 toLinear(vec3 c) {
89	  return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c));
90	}
91	
92	vec3 toSrgb(vec3 c) {
93	  c = clamp(c, 0.0, 1.0);
94	  return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c));
95	}
96	
97	void main() {
98	  vec3 real = toLinear(backdrop);
99	  if (hasVideo) {
100	    vec3 direction = toVideo * vec3(vNdc * captureTan, -1.0);
101	    vec2 uv = direction.xy / (max(-direction.z, 1e-4) * videoTan) * 0.5 + 0.5;
102	    if (direction.z < 0.0 && uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
103	      real = toLinear(texture2D(videoMap, uv).rgb);
104	    }
105	  }
106	  vec4 overlay = texture2D(virtualMap, vNdc * 0.5 + 0.5);
107	  gl_FragColor = vec4(toSrgb(overlay.rgb + real * (1.0 - overlay.a)), 1.0);
108	}`;
