180	function distanceToSegment(p: THREE.Vector3, a: THREE.Vector3, b: THREE.Vector3): number {
181	  _d.subVectors(b, a);
182	  const t = THREE.MathUtils.clamp(_c.subVectors(p, a).dot(_d) / Math.max(_d.lengthSq(), 1e-8), 0, 1);
