186	/**
187	 * 両手の親指と人差し指で四角を作ると枠が出て、どちらかの親指を倒すと、枠の中に見えている景色を写真に撮る。
188	 *
189	 * 手の形は hand-tracking の関節の位置から判定する。片手ごとに「人差し指が伸び、親指が開いている (L 字)」
190	 * ことを調べ、両手の L 字の角を対角とする四角形を、頭から見て正面を向く向きに作る。
191	 *
192	 * 撮った写真は空間に残り、つまんで持ち運べる (Holding)。
193	 *
194	 * 写真は、頭の位置から枠を通して見た範囲を、仮想物体だけレンダーターゲットに描いて作る。
195	 * WebXR のフレームバッファにはパススルー映像が入っていない (合成は OS 側で行われる) ので、
196	 * 現実の景色は getUserMedia で取ったパススルーカメラの映像から、同じ範囲を切り出して下に敷く。
197	 * カメラを許可していない場合は、仮想物体だけの写真になる。
198	 */
199	export class HandFrame implements Feature {
200	  readonly name = 'handFrame';
201	  enabled = true;
202	  /** 撮った写真。セッションを終えたあと、ページから保存できる。 */
203	  readonly photos: Photo[] = [];
204	  /** 撮った瞬間の通知 (効果音など) */
205	  onCapture: ((position: THREE.Vector3) => void) | null = null;
206	  /** 写真が画像ファイルになったときの通知 */
207	  onPhoto: ((photo: Photo) => void) | null = null;
208	
209	  private readonly left = newFrameHand();
210	  private readonly right = newFrameHand();
211	  private active = false;
212	  /** 枠の形になり始めた時刻。なっていなければ負 */
213	  private formingSince = -1;
214	  private activeSince = 0;
215	  private lastCapture = -Infinity;
216	  private flashUntil = 0;
217	
218	  /** 枠の中心・向き・大きさ */
219	  private readonly center = new THREE.Vector3();
220	  private readonly quaternion = new THREE.Quaternion();
221	  private width = 0;
222	  private height = 0;
223	
224	  private readonly frame = new THREE.Group();
225	  private readonly bars: THREE.Mesh[] = [];
226	  private readonly flash: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
227	  private readonly worldPhotos: WorldPhoto[] = [];
228	  /** 「全部消す」の回数と、復元を始めたときのその値。復元の途中で消されたことを見分ける。 */
229	  private clearGeneration = 0;
230	  private restoreGeneration = 0;
231	
232	  private readonly captureCamera = new THREE.PerspectiveCamera();
233	  // 仮想物体はリニアで描かれるので、暗部が潰れないよう 8 ビットより精度のある形式で受ける。
234	  private readonly virtualTarget = new THREE.WebGLRenderTarget(1, 1, {
235	    type: THREE.HalfFloatType,
236	    stencilBuffer: true,
237	  });
238	  private readonly outputTarget = new THREE.WebGLRenderTarget(1, 1, { depthBuffer: false });
239	  private readonly compositeMaterial = new THREE.ShaderMaterial({
240	    vertexShader: FULLSCREEN_VERTEX,
241	    fragmentShader: COMPOSITE_FRAGMENT,
242	    depthTest: false,
243	    depthWrite: false,
244	    uniforms: {
245	      virtualMap: { value: this.virtualTarget.texture },
246	      videoMap: { value: null as THREE.Texture | null },
247	      hasVideo: { value: false },
248	      toVideo: { value: new THREE.Matrix3() },
249	      captureTan: { value: new THREE.Vector2(1, 1) },
250	      videoTan: { value: new THREE.Vector2(1, 1) },
251	      backdrop: { value: new THREE.Vector3(BACKDROP.r, BACKDROP.g, BACKDROP.b) },
252	    },
253	  });
254	  private readonly compositeScene = new THREE.Scene();
255	
256	  private video: HTMLVideoElement | null = null;
257	  private videoTexture: THREE.VideoTexture | null = null;
258	  private time = 0;
259	  private lastVideoTime = 0;
260	  private videoAdvancedAt = -Infinity;
