262	  constructor(private readonly app: App) {
263	    // Color は内部でリニアに直されるので、シェーダーに渡す sRGB の値を取り直す。
264	    BACKDROP.getRGB(_clearColor, THREE.SRGBColorSpace);
265	    this.compositeMaterial.uniforms.backdrop.value.set(_clearColor.r, _clearColor.g, _clearColor.b);
