303	    // 位置と大きさは他の物と一緒に保存し、画像は大きいので別に (IndexedDB) 持つ。
304	    app.persistence.register<SavedPhoto[]>('photos', {
305	      save: () =>
306	        this.worldPhotos.map(({ id, group, width, height }) => ({
307	          id,
308	          width,
309	          height,
310	          pose: app.persistence.poseOf(group),
311	        })),
312	      restore: (saved) => {
