319	  /** カメラの映像が取れていて、写真に現実の景色が入るか */
320	  get cameraReady(): boolean {
321	    const video = this.video;
322	    return video !== null && video.readyState >= 2 && video.videoWidth > 0;
323	  }
324	
325	  /** カメラの映像が、いまも更新され続けているか。MR セッション中に止まる環境を見分けるためのもの。 */
326	  get cameraLive(): boolean {
327	    return this.cameraReady && this.time - this.videoAdvancedAt < 1;
328	  }
329	
330	  /**
331	   * カメラの映像を取り始める。許可のダイアログが出るので、MR を始める前に、
332	   * ユーザー操作 (ボタンのクリック) の中で呼ぶ。
333	   * deviceId を省くと、背面 (パススルー) のカメラらしいものを選ぶ。
334	   */
335	  async startCamera(deviceId?: string): Promise<CameraInfo | null> {
336	    const media = navigator.mediaDevices;
337	    if (!media?.getUserMedia) return null;
338	    const size = { width: { ideal: 1280 }, height: { ideal: 960 } };
339	    this.stopCamera();
340	    let stream = await media.getUserMedia({
341	      video: deviceId ? { deviceId: { exact: deviceId }, ...size } : { facingMode: 'environment', ...size },
342	    });
343	    // カメラの名前は、許可が下りたあとでないと読めない。
344	    const cameras = (await media.enumerateDevices())
345	      .filter((device) => device.kind === 'videoinput')
346	      .map((device, i) => ({ deviceId: device.deviceId, label: device.label || `カメラ ${i + 1}` }));
347	    let current = stream.getVideoTracks()[0]?.getSettings().deviceId ?? '';
348	    if (!deviceId) {
349	      // Quest のブラウザには、アバターを映す仮想カメラもある。facingMode の指定が効かずに
350	      // そちらが選ばれた場合に備えて、名前からも背面のカメラを探す。
351	      // Quest 3 では "camera 1, facing back" と "camera 2, facing back" の 2 つがあり、
352	      // 画角と傾きの値は camera 2 で合わせてあるので、そちらを優先する。
353	      const back =
354	        cameras.find((camera) => /camera 2\b.*back/i.test(camera.label)) ??
355	        cameras.find((camera) => /back|rear|environment|passthrough/i.test(camera.label));
356	      if (back && back.deviceId !== current) {
357	        for (const track of stream.getTracks()) track.stop();
358	        stream = await media.getUserMedia({ video: { deviceId: { exact: back.deviceId }, ...size } });
359	        current = back.deviceId;
360	      }
361	    }
362	
363	    const video = document.createElement('video');
364	    video.srcObject = stream;
365	    video.muted = true;
366	    video.playsInline = true;
367	    await video.play();
368	    const texture = new THREE.VideoTexture(video);
369	    // 色の変換は合成のシェーダーで自前で行うので、映像の値をそのまま読む。
370	    texture.colorSpace = THREE.NoColorSpace;
371	    this.video = video;
372	    this.videoTexture = texture;
373	    this.compositeMaterial.uniforms.videoMap.value = texture;
374	    return { video, cameras, deviceId: current };
375	  }
376	
377	  private stopCamera(): void {
378	    const stream = this.video?.srcObject as MediaStream | null | undefined;
379	    for (const track of stream?.getTracks() ?? []) track.stop();
380	    this.video?.remove();
381	    this.videoTexture?.dispose();
382	    this.video = null;
383	    this.videoTexture = null;
384	    this.compositeMaterial.uniforms.videoMap.value = null;
385	  }
386	
387	  private trackVideo(time: number): void {
388	    this.time = time;
389	    const videoTime = this.video?.currentTime ?? 0;
390	    if (videoTime !== this.lastVideoTime) {
391	      this.lastVideoTime = videoTime;
392	      this.videoAdvancedAt = time;
393	    }
394	  }
