396	  start(): void {
397	    this.active = false;
398	    this.formingSince = -1;
399	    this.left.folded = false;
400	    this.right.folded = false;
401	  }
402	
403	  end(): void {
404	    this.active = false;
405	    this.frame.visible = false;
406	    // 次のセッションでは座標が変わるので、表示は片付ける。保存してあれば、そこから戻る。
407	    for (const photo of this.worldPhotos) this.removeWorldPhoto(photo, true);
408	    this.worldPhotos.length = 0;
