411	  update(ctx: FrameContext): void {
412	    const wasActive = this.active;
413	    const leftFolded = this.left.folded;
414	    const rightFolded = this.right.folded;
415	    const input = this.app.input;
416	    const readable =
417	      this.enabled && this.readHand(ctx, input.left, this.left) && this.readHand(ctx, input.right, this.right);
418	    const shaped = readable && this.checkShape(ctx.headPosition);
419	    if (!shaped) {
420	      this.active = false;
421	      this.formingSince = -1;
422	      this.left.folded = false;
423	      this.right.folded = false;
424	    } else if (!this.active) {
425	      if (this.formingSince < 0) this.formingSince = ctx.time;
426	      if (ctx.time - this.formingSince >= FORM_DELAY) {
427	        this.active = true;
428	        this.activeSince = ctx.time;
429	      }
430	    }
431	    this.trackVideo(ctx.time);
432	
433	    if (this.active) {
434	      // 親指を倒すと手の形が変わって枠の角がずれるので、倒している間は枠を動かさない。
435	      if (!this.left.folded && !this.right.folded) this.updateRect(ctx.headPosition, ctx.headQuaternion);
436	      const pressed = (this.left.folded && !leftFolded) || (this.right.folded && !rightFolded);
437	      if (
438	        pressed &&
439	        wasActive &&
440	        ctx.time - this.activeSince > ARM_DELAY &&
441	        ctx.time - this.lastCapture > COOLDOWN
442	      ) {
443	        this.lastCapture = ctx.time;
444	        this.flashUntil = ctx.time + FLASH_DURATION;
445	        this.capture(ctx);
446	        input.left.pulse(0.8, 40);
447	        input.right.pulse(0.8, 40);
448	        this.onCapture?.(this.center);
449	      }
450	    }
451	    this.updateFrame(ctx.time);
452	  }
