454	  /** 関節の位置から、片手の形を読む。素手でない、または関節が取れなければ false。 */
455	  private readHand(ctx: FrameContext, hand: HandState, out: FrameHand): boolean {
456	    const xrHand = hand.source?.hand;
457	    if (!hand.tracked || !xrHand) return false;
458	    const { frame, refSpace } = ctx;
459	    const thumbBase = getJointPose(frame, xrHand, 'thumb-phalanx-proximal', refSpace);
460	    const thumbTip = getJointPose(frame, xrHand, 'thumb-tip', refSpace);
461	    const proximal = getJointPose(frame, xrHand, 'index-finger-phalanx-proximal', refSpace);
462	    const intermediate = getJointPose(frame, xrHand, 'index-finger-phalanx-intermediate', refSpace);
463	    const distal = getJointPose(frame, xrHand, 'index-finger-phalanx-distal', refSpace);
464	    const tip = getJointPose(frame, xrHand, 'index-finger-tip', refSpace);
465	    if (!thumbBase || !thumbTip || !proximal || !intermediate || !distal || !tip) return false;
466	
467	    copyPosition(_thumbBase, thumbBase.transform.position);
468	    copyPosition(_thumbTip, thumbTip.transform.position);
469	    const indexBase = copyPosition(_a, proximal.transform.position);
470	    const indexMiddle = copyPosition(_b, intermediate.transform.position);
471	    const indexDistal = copyPosition(_indexDistal, distal.transform.position);
472	    const indexTip = copyPosition(_indexTip, tip.transform.position);
473	    // 手の大きさによらず判定できるよう、人差し指の長さを基準にする。
474	    const indexLength =
475	      indexBase.distanceTo(indexMiddle) + indexMiddle.distanceTo(indexDistal) + indexDistal.distanceTo(indexTip);
476	    if (indexLength < 1e-4) return false;
477	    out.indexStraightness = indexBase.distanceTo(indexTip) / indexLength;
478	    out.thumbGap = distanceToSegment(_thumbTip, indexBase, indexMiddle) / indexLength;
479	    if (out.thumbGap > THUMB_OPEN) out.folded = false;
480	    else if (out.thumbGap < THUMB_FOLD) out.folded = true;
481	
482	    out.corner.addVectors(_thumbBase, indexBase).multiplyScalar(0.5);
483	    out.indexDirection.subVectors(indexTip, indexBase).normalize();
484	    out.thumbDirection.subVectors(_thumbTip, _thumbBase).normalize();
485	    return true;
486	  }
487	
488	  /** 両手が枠の形になっているか。すでに枠が出ているときは、条件をゆるめて保つ。 */
489	  private checkShape(head: THREE.Vector3): boolean {
490	    const { left, right } = this;
491	    _diagonal.subVectors(right.corner, left.corner);
492	    const distance = _diagonal.length();
493	    if (distance < MIN_SIDE || distance > MAX_SIDE * 1.5) return false;
494	    // 手が頭に近すぎる / 遠すぎるときは、枠として扱わない。
495	    const reach = _c.addVectors(left.corner, right.corner).multiplyScalar(0.5).distanceTo(head);
496	    if (reach < 0.1 || reach > 1) return false;
497	
498	    _diagonal.divideScalar(distance);
499	    const view = _normal.copy(_c).sub(head).normalize();
500	    const leftAcross = Math.abs(left.indexDirection.dot(view));
501	    const rightAcross = Math.abs(right.indexDirection.dot(view));
502	    const indexOpposed = left.indexDirection.dot(right.indexDirection);
503	
504	    if (this.active) {
505	      // 撮るために親指を倒している間も枠を保つので、親指の形は見ない。ただし両方倒したら枠をやめる。
506	      // 人差し指が前を指す、曲がる、同じ向きに揃う、のどれかで枠は消える。
507	      return (
508	        left.indexStraightness > INDEX_STRAIGHT_HOLD &&
509	        right.indexStraightness > INDEX_STRAIGHT_HOLD &&
510	        leftAcross < ACROSS_VIEW_HOLD &&
511	        rightAcross < ACROSS_VIEW_HOLD &&
512	        indexOpposed < OPPOSED_HOLD &&
513	        left.indexDirection.dot(_diagonal) > 0 &&
514	        right.indexDirection.dot(_diagonal) < 0 &&
515	        !(left.folded && right.folded)
516	      );
517	    }
518	    if (left.indexStraightness < INDEX_STRAIGHT_FORM || right.indexStraightness < INDEX_STRAIGHT_FORM) return false;
519	    if (left.folded || right.folded || left.thumbGap < THUMB_OPEN || right.thumbGap < THUMB_OPEN) return false;
520	    // 指が視線に対して横に寝ていること。レイで何かを指している手は、ここで外れる。
521	    if (leftAcross > ACROSS_VIEW_FORM || rightAcross > ACROSS_VIEW_FORM) return false;
522	    if (Math.abs(left.thumbDirection.dot(view)) > ACROSS_VIEW_HOLD) return false;
523	    if (Math.abs(right.thumbDirection.dot(view)) > ACROSS_VIEW_HOLD) return false;
524	    // 両手の L 字が、互い違いに向かい合っていること。人差し指どうし、親指どうしが逆を向き、
525	    // それぞれの指が相手の手の角へ向かう成分を持つ。両手をただ広げて並べた形は、ここで外れる。
526	    if (indexOpposed > OPPOSED_FORM) return false;
527	    if (left.thumbDirection.dot(right.thumbDirection) > OPPOSED_HOLD) return false;
528	    if (left.indexDirection.dot(_diagonal) < INWARD_MIN || left.thumbDirection.dot(_diagonal) < INWARD_MIN) return false;
529	    if (right.indexDirection.dot(_diagonal) > -INWARD_MIN || right.thumbDirection.dot(_diagonal) > -INWARD_MIN) {
530	      return false;
531	    }
532	    return true;
533	  }
534	
535	  /** 両手の角を対角とする四角形を、頭のほうを向く平面の上に作る。 */
536	  private updateRect(head: THREE.Vector3, headQuaternion: THREE.Quaternion): void {
537	    this.center.addVectors(this.left.corner, this.right.corner).multiplyScalar(0.5);
538	    _normal.subVectors(head, this.center).normalize();
539	    // 写真が傾かないよう、上辺は水平にする。真上や真下を向いているときだけ、頭の向きに合わせる。
540	    if (Math.abs(_normal.y) < 0.95) _up.set(0, 1, 0);
541	    else _up.set(0, 1, 0).applyQuaternion(headQuaternion);
542	    _up.addScaledVector(_normal, -_up.dot(_normal)).normalize();
543	    _right.crossVectors(_up, _normal);
544	    this.quaternion.setFromRotationMatrix(_matrix.makeBasis(_right, _up, _normal));
545	    _diagonal.subVectors(this.right.corner, this.left.corner);
546	    this.width = THREE.MathUtils.clamp(Math.abs(_diagonal.dot(_right)) - FINGER_INSET * 2, MIN_SIDE, MAX_SIDE);
547	    this.height = THREE.MathUtils.clamp(Math.abs(_diagonal.dot(_up)) - FINGER_INSET * 2, MIN_SIDE, MAX_SIDE);
548	  }
549	
550	  private updateFrame(time: number): void {
551	    const flashing = time < this.flashUntil;
552	    this.frame.visible = this.active || flashing;
553	    if (!this.frame.visible) return;
554	    const { width, height } = this;
555	    this.frame.position.copy(this.center);
556	    this.frame.quaternion.copy(this.quaternion);
557	    const [top, bottom, left, right] = this.bars;
558	    top.position.set(0, height / 2, 0);
559	    bottom.position.set(0, -height / 2, 0);
560	    top.scale.set(width + BORDER, BORDER, 1);
561	    bottom.scale.copy(top.scale);
562	    left.position.set(-width / 2, 0, 0);
563	    right.position.set(width / 2, 0, 0);
564	    left.scale.set(BORDER, height + BORDER, 1);
565	    right.scale.copy(left.scale);
566	    this.flash.visible = flashing;
567	    this.flash.scale.set(width, height, 1);
568	    this.flash.material.opacity = flashing ? (0.7 * (this.flashUntil - time)) / FLASH_DURATION : 0;
569	  }
