571	  /** 頭の位置から枠を通して見た範囲を、写真にする。 */
572	  private capture(ctx: FrameContext): void {
573	    const { renderer, scene } = this.app;
574	    const { width, height } = this;
575	    const distance = Math.max(ctx.headPosition.distanceTo(this.center), 0.05);
576	    const scale = CAPTURE_SIZE / Math.max(width, height);
577	    const pixelWidth = Math.max(Math.round(width * scale), 2);
578	    const pixelHeight = Math.max(Math.round(height * scale), 2);
579	
580	    // 枠は頭の正面を向けて作ってあるので、視線の軸に対して左右・上下が対称な、普通の透視投影になる。
581	    const camera = this.captureCamera;
582	    camera.position.copy(ctx.headPosition);
583	    camera.quaternion.copy(this.quaternion);
584	    camera.fov = THREE.MathUtils.radToDeg(2 * Math.atan(height / 2 / distance));
585	    camera.aspect = width / height;
586	    // 枠より手前にあるもの (手のカーソルなど) は写さない。
587	    camera.near = distance;
588	    camera.far = 50;
589	    camera.updateProjectionMatrix();
590	
591	    const uniforms = this.compositeMaterial.uniforms;
592	    uniforms.captureTan.value.set(width / 2 / distance, height / 2 / distance);
593	    const video = this.video;
594	    const hasVideo = this.cameraReady && video !== null && this.videoTexture !== null;
595	    uniforms.hasVideo.value = hasVideo;
596	    if (hasVideo) {
597	      // XR セッション中は映像の更新通知が来ないことがあるので、撮る直前に必ず取り込み直す。
598	      this.videoTexture!.needsUpdate = true;
599	      const tanHorizontal = Math.tan(THREE.MathUtils.degToRad(CAMERA_FOV_HORIZONTAL / 2));
600	      uniforms.videoTan.value.set(tanHorizontal, (tanHorizontal * video.videoHeight) / video.videoWidth);
601	      // カメラは頭に固定されているものとして、枠の向き → カメラの向き の回転を求める。
602	      _quaternion.copy(ctx.headQuaternion).multiply(CAMERA_TILT).invert().multiply(this.quaternion);
603	      uniforms.toVideo.value.setFromMatrix4(_matrix.makeRotationFromQuaternion(_quaternion));
604	    }
605	
606	    this.virtualTarget.setSize(pixelWidth, pixelHeight);
607	    this.outputTarget.setSize(pixelWidth, pixelHeight);
608	    const pixels = new Uint8Array(pixelWidth * pixelHeight * 4);
609	
610	    // XR セッション中の renderer は、XR のカメラで XR のフレームバッファへ描く。
611	    // その設定を一時的に外して、自前のカメラでレンダーターゲットへ描く。
612	    const previousTarget = renderer.getRenderTarget();
613	    const previousXr = renderer.xr.enabled;
614	    const previousAlpha = renderer.getClearAlpha();
615	    renderer.getClearColor(_clearColor);
616	    const frameVisible = this.frame.visible;
617	    this.frame.visible = false;
618	    // 前に撮った写真は写さない。同じ場所で続けて撮ると、前の写真が景色を覆ってしまう。
619	    for (const photo of this.worldPhotos) photo.group.visible = false;
620	    try {
621	      renderer.xr.enabled = false;
622	      renderer.setClearColor(0x000000, 0);
623	      renderer.setRenderTarget(this.virtualTarget);
624	      withoutOcclusion(() => renderer.render(scene, camera));
625	      renderer.setRenderTarget(this.outputTarget);
626	      renderer.render(this.compositeScene, camera);
627	      renderer.readRenderTargetPixels(this.outputTarget, 0, 0, pixelWidth, pixelHeight, pixels);
628	    } finally {
629	      renderer.setRenderTarget(previousTarget);
630	      renderer.setClearColor(_clearColor, previousAlpha);
631	      renderer.xr.enabled = previousXr;
632	      this.frame.visible = frameVisible;
633	      for (const photo of this.worldPhotos) photo.group.visible = true;
634	    }
635	
636	    // 読み出した画素は下の行から並んでいるので、上下を入れ替えてキャンバスに置く。
637	    const canvas = document.createElement('canvas');
638	    canvas.width = pixelWidth;
639	    canvas.height = pixelHeight;
640	    const context = canvas.getContext('2d');
641	    if (!context) return;
642	    const image = context.createImageData(pixelWidth, pixelHeight);
643	    const rowBytes = pixelWidth * 4;
644	    for (let y = 0; y < pixelHeight; y++) {
645	      const source = (pixelHeight - 1 - y) * rowBytes;
646	      image.data.set(pixels.subarray(source, source + rowBytes), y * rowBytes);
647	    }
648	    context.putImageData(image, 0, 0);
649	
650	    const worldPhoto = this.addWorldPhoto(canvas);
651	    const name = `mr-playroom-${new Date().toISOString().replace(/[:.]/g, '-')}.jpg`;
652	    canvas.toBlob(
653	      (blob) => {
654	        if (!blob) return;
655	        if (this.worldPhotos.includes(worldPhoto)) {
656	          putBlob(worldPhoto.id, blob).catch((error: unknown) => {
657	            console.warn('[handFrame] 写真の画像を保存できませんでした。次回は復元されません', error);
658	          });
659	        }
660	        const photo: Photo = { url: URL.createObjectURL(blob), name };
661	        this.photos.push(photo);
662	        this.onPhoto?.(photo);
663	      },
664	      'image/jpeg',
665	      0.92,
666	    );
667	  }
668	
669	  /** 撮った写真を、撮った場所に浮かべて残す。 */
670	  private addWorldPhoto(canvas: HTMLCanvasElement): WorldPhoto {
671	    const texture = new THREE.CanvasTexture(canvas);
672	    const worldPhoto = this.createWorldPhoto(crypto.randomUUID(), texture, this.width, this.height);
673	    const photo = worldPhoto.group;
674	    // 枠のあった場所に、枠と同じ大きさで置く。撮った景色にそのまま重なる。
675	    // 同じ場所で続けて撮るときは、撮る間だけ前の写真を隠すので、景色は塞がない。
676	    photo.quaternion.copy(this.quaternion);
677	    photo.position.copy(this.center);
678	    while (this.worldPhotos.length > MAX_WORLD_PHOTOS) this.removeWorldPhoto(this.worldPhotos.shift()!);
679	    return worldPhoto;
680	  }
681	
682	  /** 写真の板を作ってシーンに足す。位置・向き・大きさは呼び出し側が決める。width と height は撮った枠の大きさ (m)。 */
683	  private createWorldPhoto(id: string, texture: THREE.Texture, width: number, height: number): WorldPhoto {
684	    texture.colorSpace = THREE.SRGBColorSpace;
685	    const photo = new THREE.Group();
686	    const picture = new THREE.Mesh(
687	      new THREE.PlaneGeometry(width, height),
688	      new THREE.MeshBasicMaterial({ map: texture, side: THREE.DoubleSide }),
689	    );
690	    const mount = new THREE.Mesh(
691	      new THREE.PlaneGeometry(width + 0.012, height + 0.012),
692	      new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide }),
693	    );
694	    mount.position.z = -0.001;
695	    photo.add(mount, picture);
696	    this.app.scene.add(photo);
697	    const halfWidth = width / 2;
698	    const halfHeight = height / 2;
699	    this.app.holding.add({
700	      object: photo,
701	      // 枠を作っている手が、枠の位置にある写真をつまんでしまわないようにする。
702	      canHold: () => !this.active,
703	      distanceTo: (point) => {
704	        const local = photo.worldToLocal(_a.copy(point));
705	        const x = Math.max(Math.abs(local.x) - halfWidth, 0);
706	        const y = Math.max(Math.abs(local.y) - halfHeight, 0);
707	        return Math.hypot(x, y, local.z) * photo.scale.x;
708	      },
709	    });
710	    const worldPhoto: WorldPhoto = { id, group: photo, width, height };
711	    this.worldPhotos.push(worldPhoto);
712	    return worldPhoto;
713	  }
714	
715	  /** 保存してあった写真を、画像を読み直して作り直す。 */
716	  private async restoreWorldPhotos(saved: SavedPhoto[]): Promise<void> {
717	    const session = this.app.session;
718	    for (const { id, width, height, pose } of saved) {
719	      const blob = await getBlob(id);
720	      // 撮った直後にページを閉じると、画像の保存が間に合っていないことがある。
721	      if (!blob) continue;
722	      const url = URL.createObjectURL(blob);
723	      try {
724	        const texture = await new THREE.TextureLoader().loadAsync(url);
725	        // 読み込みを待つ間に、セッションが終わったり「全部消す」が押されたりしていたら、作らない。
726	        if (this.app.session !== session || this.restoreGeneration !== this.clearGeneration) {
727	          texture.dispose();
728	          return;
729	        }
730	        this.app.persistence.place(this.createWorldPhoto(id, texture, width, height).group, pose);
731	      } finally {
732	        URL.revokeObjectURL(url);
733	      }
734	    }
735	  }
736	
737	  private clearWorldPhotos(): void {
738	    this.clearGeneration++;
739	    for (const photo of this.worldPhotos) this.removeWorldPhoto(photo);
740	    this.worldPhotos.length = 0;
741	  }
742	
743	  /** keepImage: 保存してある画像を残す (セッションの終了で、表示だけ片付けるとき) */
744	  private removeWorldPhoto({ id, group: photo }: WorldPhoto, keepImage = false): void {
745	    if (!keepImage) void deleteBlob(id).catch(() => {});
746	    this.app.scene.remove(photo);
747	    this.app.holding.remove(photo);
748	    for (const child of photo.children) {
749	      const mesh = child as THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
750	      mesh.geometry.dispose();
751	      mesh.material.map?.dispose();
752	      mesh.material.dispose();
753	    }
754	  }
755	}
