24	/** immersive-ar が使えるかを調べ、使えるときだけ開始ボタンを有効にする。 */
25	export async function setupEnterButton(onEnter: () => void): Promise<void> {
26	  enterButton.addEventListener('click', onEnter);
27	  if (!navigator.xr) {
28	    setMessage('このブラウザは WebXR に対応していません。Meta Quest のブラウザで、HTTPS で開いてください。');
