export interface CameraControl {
  /** deviceId のカメラ (省略時はおまかせ) の映像を取り始める。使えなければ null を返す。 */
  start(deviceId?: string): Promise<CameraInfo | null>;
  /** 使用中のカメラを止め、待っている要求も取り消す */
  stop(): void;
}

export interface CameraButton {
  /** カメラがページの外の理由 (MR の終了など) で止まったことを、表示に反映する */
  stopped(reason: CameraStopReason): void;
  /** 「手で撮影」をオフにして止めたカメラを、オンに戻したときに再開する */
  resume(): void;
}

const STOP_MESSAGES: Record<CameraStopReason, string> = {
  user: 'カメラを止めました。写真に現実の景色を入れるときは、もう一度開始してください。',
  'session-end': 'MR を終えたので、カメラを止めました。次の MR の前に、もう一度開始してください。',
  disabled: '「手で撮影」をオフにしたので、カメラを止めました。オンに戻すと再開します。',
  pagehide: 'ページを離れたので、カメラを止めました。',
  'track-ended': 'カメラの映像が途切れました (許可の取り消しなど)。使うときは、もう一度開始してください。',
};

function readSavedCamera(): string | undefined {
  try {
    return localStorage.getItem(CAMERA_KEY) ?? undefined;
  } catch {
    return undefined;
  }
}

function saveCamera(deviceId: string): void {
  try {
    localStorage.setItem(CAMERA_KEY, deviceId);
  } catch {
    // 覚えられなくても、今回の選択には影響しない。
  }
}

/**
 * カメラの開始・停止ボタン。許可のダイアログは MR セッション中には出せないので、開始前に押してもらう。
 * 取れた映像はページに表示し、どのカメラが使われているかを目で確かめられるようにする。
 * Quest では、このプレビューは MR に入っても止めずに使い続け (写真の背景になる)、MR を終えたら止める。
 */
export function setupCameraButton(control: CameraControl): CameraButton {
  const button = document.querySelector<HTMLButtonElement>('#camera')!;
  const status = document.querySelector<HTMLSpanElement>('#camera-status')!;
  const preview = document.querySelector<HTMLDivElement>('#camera-preview')!;
  const select = document.querySelector<HTMLSelectElement>('#camera-select')!;

  let state: 'idle' | 'requesting' | 'running' | 'unsupported' = 'idle';
  /** 要求ごとに増やす。古い要求の結果が、あとから表示を書き換えないようにする。 */
  let generation = 0;
  /** 一度でも許可が下りたか (ボタンの文言を「許可」から「開始」に変える) */
  let granted = false;
  let currentDevice: string | undefined;
  /** 「手で撮影」のオフで止めたときの、再開するカメラ。再開するものがなければ null */
  let resumeDevice: string | undefined | null = null;

  const render = (): void => {
    button.disabled = state === 'unsupported';
    button.textContent =
      state === 'requesting' ? '待つのをやめる' : state === 'running' ? 'カメラを止める' : granted ? 'カメラを開始' : 'カメラを許可';
    select.disabled = state !== 'running';
    preview.hidden = state !== 'running';
  };

  const toIdle = (message: string): void => {
    generation++;
    state = 'idle';
    // 映像の要素は HandFrame が止めて外すが、念のためプレビューからも外す。
    preview.querySelector('video')?.remove();
    status.textContent = message;
    render();
  };

  const start = (deviceId?: string): void => {
    const id = ++generation;
    state = 'requesting';
    status.textContent = 'カメラの映像を待っています…';
    render();
    control
      .start(deviceId)
      // 覚えていたカメラが無くなっていた場合は、おまかせで選び直す。取り消された場合は選び直さない。
      .catch((error: unknown) =>
        deviceId && id === generation && !(error instanceof CameraCancelledError) ? control.start() : Promise.reject(error),
      )
      .then(
        (info) => {
          // 待っている間に止められた、または次の要求が出ていたら、この結果は表示しない。
          // (映像のほうは、HandFrame が止めてある。)
          if (id !== generation) return;
          if (!info) {
            state = 'unsupported';
            status.textContent = 'このブラウザではカメラを使えません。写真は仮想物体だけになります。';
            render();
            return;
          }
          const { video, cameras } = info;
          state = 'running';
          granted = true;
          currentDevice = info.deviceId;
          status.textContent = `カメラを使えます (${video.videoWidth}×${video.videoHeight})。`;
          select.replaceChildren(...cameras.map((camera) => new Option(camera.label, camera.deviceId)));
          select.value = info.deviceId;
          preview.querySelector('video')?.remove();
          preview.append(video);
          render();
        },
        (error: unknown) => {
          if (id !== generation || error instanceof CameraCancelledError) return;
          console.error(error);
          toIdle(`カメラを使えませんでした: ${error instanceof Error ? error.message : String(error)}`);
        },
      );
  };

  button.addEventListener('click', () => {
    if (state === 'requesting' || state === 'running') {
      resumeDevice = null;
      toIdle(state === 'running' ? STOP_MESSAGES.user : 'カメラを待つのをやめました。');
      control.stop();
      return;
    }
    // Quest のブラウザは、既定ではアバターを映す仮想カメラを選ぶ。名前からは見分けられないので、
    // 一度選んでもらったカメラを覚えておき、次回からはそれを使う。
    resumeDevice = null;
    start(readSavedCamera());
  });
  select.addEventListener('change', () => {
    saveCamera(select.value);
    start(select.value);
  });
  render();

  return {
    stopped(reason) {
      // ページのボタンで止めたときは、すでに表示を変えてある。
      if (reason === 'user') return;
      const wasRunning = state === 'running';
      resumeDevice = reason === 'disabled' && (wasRunning || state === 'requesting') ? currentDevice : null;
      toIdle(STOP_MESSAGES[reason]);
    },
    resume() {
      if (resumeDevice === null || state !== 'idle') return;
      const deviceId = resumeDevice;
      resumeDevice = null;
      start(deviceId);
    },
  };
}

const id = ++generation;
state = 'requesting';
// 待っている間にオフにされたら、このカメラで再開する。取れたら実際のカメラに置き換える。
currentDevice = deviceId;

const cameraButton = setupCameraButton({
  start: (deviceId) => handFrame.startCamera(deviceId),
  stop: () => handFrame.stopCamera('user'),
});
// MR の終了・「手で撮影」のオフ・ページを離れたときなど、ページの外の理由で止まったカメラを表示に反映する。
handFrame.onCameraStop = (reason) => cameraButton.stopped(reason);
handFrame.onEnabledChange = (enabled) => {
  if (enabled) cameraButton.resume();
};

