// Run from repo root: deno run -A --node-modules-dir=manual <this file>
const repo = Deno.cwd().replaceAll('\\', '/');
let stopped: string[] = [];
let nextId = 0;
const deferred: { resolve: (s: unknown) => void }[] = [];
function makeStream() {
  const id = `s${++nextId}`;
  const track = {
    stop: () => stopped.push(id),
    getSettings: () => ({ deviceId: 'dev2' }),
    addEventListener: (_: string, fn: () => void) => ((track as any).onended = fn),
  };
  return { id, track, getTracks: () => [track], getVideoTracks: () => [track] };
}
let manual = false;
(globalThis as any).navigator = {
  mediaDevices: {
    getUserMedia: () => (manual ? new Promise((resolve) => deferred.push({ resolve })) : Promise.resolve(makeStream())),
    enumerateDevices: async () => [{ kind: 'videoinput', deviceId: 'dev2', label: 'camera 2, facing back' }],
  },
};
let playFails = false;
(globalThis as any).document = {
  createElement: () => ({
    play: () => (playFails ? Promise.reject(new Error('play failed')) : Promise.resolve()),
    pause() {},
    remove() {},
    srcObject: null,
  }),
};
(globalThis as any).window = { addEventListener() {} };

const { HandFrame, CameraCancelledError } = await import(`file:///${repo}/src/features/handFrame.ts`);
const self: any = Object.create(HandFrame.prototype);
Object.assign(self, {
  _enabled: true,
  cameraRequest: 0,
  pendingRequest: 0,
  stream: null,
  video: null,
  videoTexture: null,
  compositeMaterial: { uniforms: { videoMap: { value: null } } },
  onCameraStop: null,
  onEnabledChange: null,
});
const stops: string[] = [];
self.onCameraStop = (r: string) => stops.push(r);
const assert = (c: boolean, m: string) => {
  if (!c) throw new Error('FAIL: ' + m);
  console.log('ok -', m);
};

// 1. normal start then stop
await self.startCamera('dev2');
assert(self.cameraActive, 'started');
self.stopCamera('session-end');
assert(!self.cameraActive && stopped.includes('s1') && stops.at(-1) === 'session-end', 'stop on session end');

// 2. stop while waiting for permission
manual = true;
const p = self.startCamera('dev2');
self.stopCamera('user');
assert(stops.at(-1) === 'user', 'pending stop notifies');
deferred.shift()!.resolve(makeStream());
const r = await p.then(() => 'ok', (e: unknown) => e);
assert(r instanceof CameraCancelledError && stopped.includes('s2') && !self.cameraActive, 'late stream stopped, cancelled');

// 3. older request resolving after newer one
const a = self.startCamera('dev2');
const b = self.startCamera('dev2');
deferred[1].resolve(makeStream()); // s3 -> b
deferred[0].resolve(makeStream()); // s4 -> a (stale)
deferred.length = 0;
const [ra, rb] = await Promise.all([a.then(() => 'ok', (e: unknown) => e), b]);
assert(ra instanceof CameraCancelledError && stopped.includes('s4') && !stopped.includes('s3'), 'stale request stopped');
assert(self.cameraActive && rb.deviceId === 'dev2', 'newer request active');

// 4. disabling stops
manual = false;
self.enabled = false;
assert(!self.cameraActive && stopped.includes('s3') && stops.at(-1) === 'disabled', 'disable stops');
self.enabled = true;

// 5. failure after acquisition
playFails = true;
const before = stopped.length;
const rf = await self.startCamera('dev2').then(() => 'ok', (e: unknown) => e);
assert(rf instanceof Error && stopped.length === before + 1 && !self.cameraActive, 'play failure stops track');
playFails = false;

// 6. track ended externally
await self.startCamera('dev2');
self.stream.getTracks()[0].onended();
assert(!self.cameraActive && stops.at(-1) === 'track-ended', 'track ended cleanup');
console.log('all ok');
